using Meziantou.Framework.WebPlatform.Css.Fonts;
using Meziantou.Framework.WebPlatform.Unicode;

namespace Meziantou.Framework.WebPlatform.Tests.Css.Fonts;

/// <summary>
/// The complex-script shapers (the ports of the HarfBuzz shapers): with ComplexShapingTest.ttf, a synthetic font without
/// OpenType layout tables generated by <c>Resources/make-complex-shaping-test-font.py</c> (the processing that does not
/// depend on the features of the font: Thai, Hebrew, Hangul, Khmer and the Arabic fallback shaping), and with the Noto Sans
/// Devanagari font of the WPT (the Indic reordering). <see cref="HarfBuzzShapingTests"/> runs the tests of HarfBuzz.
/// </summary>
public sealed class ComplexScriptShapingTests
{
    // The glyph ids of ComplexShapingTest.ttf
    private const int DottedCircle = 2;
    private const int KoKai = 3, PoPla = 4, SaraAa = 6, Nikhahit = 8, MaiEk = 9, SaraU = 10, MaiEkShiftedDownLeft = 11, YoYingWithoutDescender = 12;
    private const int BetDagesh = 15, ShinShinDot = 18;
    private const int Ga = 22, Gag = 23, Tone = 24;
    private const int Ka = 25, E = 26, Oe = 27;
    private const int BehIsolated = 33, BehInitial = 35, LamAlefIsolated = 41, LamAlefFinal = 42;

    private static readonly OpenTypeFont TestFont = FontFile.Load(File.ReadAllBytes(Path.Combine(TestPaths.Root, "tests", "Meziantou.Framework.WebPlatform.Tests", "Css", "Fonts", "Resources", "ComplexShapingTest.ttf")))!.Faces[0];

    private static (int[] Glyphs, int[] Clusters) Shape(OpenTypeFont font, string text, UnicodeScript script, ShapingDirection direction = ShapingDirection.LeftToRight)
    {
        using var buffer = new ShapingBuffer();
        font.Shape(text, script, direction, language: null, features: null, instance: null, buffer);
        var glyphs = new int[buffer.Length];
        var clusters = new int[buffer.Length];
        for (var i = 0; i < buffer.Length; i++)
        {
            glyphs[i] = buffer.Info[i].Codepoint;
            clusters[i] = buffer.Info[i].Cluster;
        }

        return (glyphs, clusters);
    }

    [Fact]
    public void Thai_SaraAm_IsDecomposed()
    {
        // NIKHAHIT + SARA AA, in the cluster of the consonant
        var (glyphs, clusters) = Shape(TestFont, "กำ", UnicodeScript.Thai);
        Assert.Equal([KoKai, Nikhahit, SaraAa], glyphs);
        Assert.Equal([0, 0, 0], clusters);
    }

    [Fact]
    public void Thai_SaraAm_NikhahitMovesBeforeTheAboveMarks()
    {
        Assert.Equal([KoKai, Nikhahit, MaiEk, SaraAa], Shape(TestFont, "ก่ำ", UnicodeScript.Thai).Glyphs);
    }

    [Fact]
    public void Thai_PrivateUseAreaFallback()
    {
        // The font has no Thai GSUB: the tone mark on a consonant with an ascender is shifted down and left, and the descender
        // of YO YING is removed before a below vowel (the glyphs of the Windows fonts)
        Assert.Equal([PoPla, MaiEkShiftedDownLeft], Shape(TestFont, "ป่", UnicodeScript.Thai).Glyphs);
        Assert.Equal([YoYingWithoutDescender, SaraU], Shape(TestFont, "ญุ", UnicodeScript.Thai).Glyphs);
    }

    [Theory]
    [InlineData("בּ", BetDagesh)]
    [InlineData("שׁ", ShinShinDot)]
    public void Hebrew_PresentationForms(string text, int expected)
    {
        // The font has no GPOS mark positioning: the marks are composed with the presentation forms
        Assert.Equal([expected], Shape(TestFont, text, UnicodeScript.Hebrew, ShapingDirection.RightToLeft).Glyphs);
    }

    [Theory]
    [InlineData("가", Ga)]
    [InlineData("각", Gag)]
    [InlineData("각", Gag)]
    public void Hangul_JamosAreComposed(string text, int expected)
    {
        var (glyphs, clusters) = Shape(TestFont, text, UnicodeScript.Hangul);
        Assert.Equal([expected], glyphs);
        Assert.Equal([0], clusters);
    }

    [Fact]
    public void Hangul_ToneMark()
    {
        // A tone mark after a syllable moves before it; without a syllable, it gets a dotted circle
        Assert.Equal([Tone, Ga], Shape(TestFont, "가〮", UnicodeScript.Hangul).Glyphs);
        Assert.Equal([Tone, DottedCircle], Shape(TestFont, "〮", UnicodeScript.Hangul).Glyphs);
    }

    [Fact]
    public void Khmer_SplitVowelIsDecomposedAndReordered()
    {
        // KA + OE: OE is E (a left matra, moved before the base) + OE
        var (glyphs, clusters) = Shape(TestFont, "កើ", UnicodeScript.Khmer);
        Assert.Equal([E, Ka, Oe], glyphs);
        Assert.Equal([0, 0, 0], clusters);
    }

    [Fact]
    public void Arabic_FallbackShaping()
    {
        // The font has no GSUB: its presentation forms give the joining forms and the lam-alef ligatures
        Assert.Equal([BehIsolated], Shape(TestFont, "ب", UnicodeScript.Arabic, ShapingDirection.RightToLeft).Glyphs);
        Assert.Equal([LamAlefIsolated], Shape(TestFont, "لا", UnicodeScript.Arabic, ShapingDirection.RightToLeft).Glyphs);
        Assert.Equal([BehInitial, LamAlefFinal], Shape(TestFont, "بلا", UnicodeScript.Arabic, ShapingDirection.RightToLeft).Glyphs);
    }

    private static OpenTypeFont LoadDevanagari() => FontFile.Load(File.ReadAllBytes(TestPaths.External("wpt", "fonts", "noto", "NotoSansDevanagari-Regular.ttf")))!.Faces[0];

    [Fact]
    public void Devanagari_PreBaseMatraIsReordered()
    {
        // KA + I: the matra is drawn before the consonant
        var font = LoadDevanagari();
        var (glyphs, clusters) = Shape(font, "कि", UnicodeScript.Devanagari);
        Assert.Equal(2, glyphs.Length);
        Assert.NotEqual(font.GetGlyphId(0x0915), glyphs[0]);
        Assert.Equal(font.GetGlyphId(0x0915), glyphs[1]);
        Assert.Equal([0, 0], clusters);
    }

    [Fact]
    public void Devanagari_Reph()
    {
        // RA + VIRAMA + KA: the reph form of RA is after the base
        var font = LoadDevanagari();
        var glyphs = Shape(font, "र्क", UnicodeScript.Devanagari).Glyphs;
        Assert.Equal(2, glyphs.Length);
        Assert.Equal(font.GetGlyphId(0x0915), glyphs[0]);
        Assert.NotEqual(font.GetGlyphId(0x0930), glyphs[1]);
    }

    [Fact]
    public void Devanagari_Conjunct()
    {
        // KA + VIRAMA + SSA is one glyph (akhn)
        var glyphs = Shape(LoadDevanagari(), "क्ष", UnicodeScript.Devanagari).Glyphs;
        Assert.Single(glyphs);
    }

    [Fact]
    public void Devanagari_BrokenSyllableGetsDottedCircle()
    {
        // A matra without a consonant: a dotted circle is inserted (after the reordering, the matra is before it)
        var font = LoadDevanagari();
        var (glyphs, clusters) = Shape(font, "ि", UnicodeScript.Devanagari);
        Assert.Equal(2, glyphs.Length);
        Assert.Equal(font.GetGlyphId(SyllabicShaping.DottedCircle), glyphs[1]);
        Assert.Equal([0, 0], clusters);
    }

    [Fact]
    public void Devanagari_ProhibitedVowelSequenceGetsDottedCircle()
    {
        // LETTER A + VOWEL SIGN AA looks like LETTER AA: a dotted circle is inserted between them
        var font = LoadDevanagari();
        var glyphs = Shape(font, "अा", UnicodeScript.Devanagari).Glyphs;
        Assert.Equal([font.GetGlyphId(0x0905), font.GetGlyphId(SyllabicShaping.DottedCircle), font.GetGlyphId(0x093E)], glyphs.Select(glyph => (ushort)glyph));
    }
}
